cat > $P/features/checkout-pricing-loyalty-discount.feature <<'EOF'
@loyalty-discount
Feature: Loyalty discount at checkout
  A returning customer's loyalty tier is reflected in the checkout total.

  # SETTLED  : AC-1 .. AC-3 (Bronze, Silver, Gold) — values copied from ac.md.
  # AMBIGUOUS: AC-4 — title says "in the customer's favour" but the expected value (7 cents
  #            charged on 7) means the reduction was rounded down to 0. Escalated to DISCUSS.
  # UNDECIDED: Platinum tier — no agreed reduction, so NO scenario exists. Do not invent one.

  @happy-path @smoke
  Scenario: Bronze customer is charged 9500 cents on a 10000 cent basket
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Silver customer is charged 9000 cents on a 10000 cent basket
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Gold customer is charged 8500 cents on a 10000 cent basket
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @edge-case @needs-clarification
  Scenario: Bronze customer is charged 7 cents on a 7 cent basket
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
EOF
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    [Fact]
    public void Bronze_customer_is_charged_9500_cents_on_a_10000_cent_basket()
    {
        var handler = new CalculateLoyaltyDiscount();

        var quote = handler.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }
}
EOF
